using System.Diagnostics;
using System.Text.Json.Serialization;
using System.Threading.RateLimiting;
using Microsoft.AspNetCore.Authentication;
using Microsoft.AspNetCore.DataProtection;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using SaigonGuide.Api.Data;
using SaigonGuide.Api.Domain;
using SaigonGuide.Api.Security;
using SaigonGuide.Api.Services;

var builder = WebApplication.CreateBuilder(args);

// Private desktop configuration, generated by scripts/local.py and ignored by Git.
// Environment variables and command-line arguments retain higher precedence.
if (builder.Environment.IsDevelopment())
{
    builder.Configuration.AddJsonFile(
        Path.GetFullPath(
            Path.Combine(builder.Environment.ContentRootPath, "../../.local/ide-settings.json")
        ),
        optional: true
    );
    builder.Configuration.AddEnvironmentVariables();
    builder.Configuration.AddCommandLine(args);
}
builder.Services.AddDbContext<GuideDb>(o =>
    o.UseNpgsql(
        builder.Configuration.GetConnectionString("Database")
            ?? throw new InvalidOperationException(
                "Configure ConnectionStrings__Database securely."
            )
    )
);
builder.Services.AddScoped<AuthService>();
builder.Services.AddScoped<ContentService>();
builder.Services.AddScoped<MediaService>();
builder.Services.AddScoped<AnalyticsService>();
builder.Services.AddScoped<DashboardService>();
builder.Services.AddSingleton<LoginGate>();
builder.Services.AddSingleton<EventThrottle>();
builder.Services.AddScoped<IPasswordHasher<User>, PasswordHasher<User>>();
builder
    .Services.AddAuthentication("Session")
    .AddScheme<AuthenticationSchemeOptions, SessionHandler>("Session", null);
builder.Services.AddAuthorization();
builder.Services.AddAntiforgery(o =>
{
    o.HeaderName = "X-CSRF-TOKEN";
    o.Cookie.Name = "sg_csrf";
    o.Cookie.HttpOnly = true;
    o.Cookie.SameSite = SameSiteMode.Lax;
    o.Cookie.SecurePolicy = builder.Environment.IsProduction()
        ? CookieSecurePolicy.Always
        : CookieSecurePolicy.SameAsRequest;
});
builder.Services.AddScoped<CsrfFilter>();
builder
    .Services.AddControllers(o => o.Filters.AddService<CsrfFilter>())
    .AddJsonOptions(o =>
        o.JsonSerializerOptions.UnmappedMemberHandling = JsonUnmappedMemberHandling.Disallow
    );
builder.Services.Configure<ApiBehaviorOptions>(o =>
    o.InvalidModelStateResponseFactory = c => new UnprocessableEntityObjectResult(
        new
        {
            title = "Dữ liệu không hợp lệ",
            status = 422,
            errors = c
                .ModelState.Where(x => x.Value?.Errors.Count > 0)
                .ToDictionary(
                    x => x.Key,
                    x => new[] { "Trường dữ liệu không hợp lệ hoặc không được cho phép." }
                ),
            traceId = c.HttpContext.TraceIdentifier,
        }
    )
);
var keyPath = Path.GetFullPath(
    builder.Configuration["Keys:Path"]
        ?? Path.Combine(builder.Environment.ContentRootPath, "../../.local/keys")
);
Directory.CreateDirectory(keyPath);
builder
    .Services.AddDataProtection()
    .PersistKeysToFileSystem(new DirectoryInfo(keyPath))
    .SetApplicationName("SaigonGuide");
builder.Services.AddRateLimiter(o =>
{
    o.RejectionStatusCode = 429;
    o.GlobalLimiter = PartitionedRateLimiter.Create<HttpContext, string>(c =>
        RateLimitPartition.GetFixedWindowLimiter(
            c.Connection.RemoteIpAddress?.ToString() ?? "unknown",
            _ =>
                new()
                {
                    PermitLimit = 600,
                    Window = TimeSpan.FromMinutes(1),
                    QueueLimit = 0,
                }
        )
    );
});
builder.Services.AddHttpClient("tiles", c => c.Timeout = TimeSpan.FromSeconds(15));
builder.Services.AddResponseCompression(o =>
{
    o.EnableForHttps = true;
    o.MimeTypes =
        Microsoft.AspNetCore.ResponseCompression.ResponseCompressionDefaults.MimeTypes.Concat(
            new[] { "text/javascript", "application/json" }
        );
});
builder.Services.AddHostedService<RetentionWorker>();
var app = builder.Build();
if (Environment.GetEnvironmentVariable("SG_COMMAND") is string command)
{
    await using var scope = app.Services.CreateAsyncScope();
    var db = scope.ServiceProvider.GetRequiredService<GuideDb>();
    if (command == "migrate")
        await db.Database.MigrateAsync();
    else if (command == "seed")
        await Seeder.Seed(
            db,
            scope.ServiceProvider.GetRequiredService<ContentService>(),
            app.Configuration,
            app.Environment
        );
    else if (command == "admin")
        await Seeder.Admin(
            db,
            app.Configuration,
            scope.ServiceProvider.GetRequiredService<IPasswordHasher<User>>()
        );
    else
        throw new InvalidOperationException("Unknown SG_COMMAND");
    return;
}
app.Use(
    async (c, next) =>
    {
        try
        {
            c.Response.Headers["X-Content-Type-Options"] = "nosniff";
            c.Response.Headers["Referrer-Policy"] = "strict-origin-when-cross-origin";
            c.Response.Headers["X-Frame-Options"] = "DENY";
            c.Response.Headers["Permissions-Policy"] =
                "geolocation=(self), microphone=(), camera=()";
            c.Response.Headers["Content-Security-Policy"] =
                "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; img-src 'self' data: https://*.tile.openstreetmap.org https://images.unsplash.com; media-src 'self'; connect-src 'self' https://*.tile.openstreetmap.org; object-src 'none'; base-uri 'self'; frame-ancestors 'none'";
            await next();
        }
        catch (Exception e)
        {
            if (c.Response.HasStarted)
                throw;
            var status = e switch
            {
                ApiError a => a.Status,
                DbUpdateConcurrencyException => 409,
                BadHttpRequestException b => b.StatusCode,
                OperationCanceledException => 499,
                _ => 500,
            };
            if (status == 500)
                app.Logger.LogError(
                    "Request {Id} failed ({Type})",
                    c.TraceIdentifier,
                    e.GetType().Name
                );
            c.Response.StatusCode = status;
            await c.Response.WriteAsJsonAsync(
                new
                {
                    title = status == 500 ? "Lỗi hệ thống" : "Không thể thực hiện",
                    status,
                    detail = status == 500 ? "Có lỗi xảy ra. Vui lòng thử lại." : e.Message,
                    traceId = c.TraceIdentifier,
                }
            );
        }
    }
);
app.UseStatusCodePages(async context =>
{
    var c = context.HttpContext;
    await c.Response.WriteAsJsonAsync(
        new
        {
            title = "Yêu cầu không được chấp nhận",
            status = c.Response.StatusCode,
            detail = c.Response.StatusCode == 401 ? "Vui lòng đăng nhập."
            : c.Response.StatusCode == 403 ? "Bạn không có quyền thực hiện thao tác."
            : "Yêu cầu không hợp lệ hoặc tài nguyên không tồn tại.",
            traceId = c.TraceIdentifier,
        }
    );
});
app.UseResponseCompression();
app.UseRateLimiter();
app.UseAuthentication();
app.UseAuthorization();
app.UseDefaultFiles();
app.UseStaticFiles();
app.MapControllers();
app.MapGet("/health/live", () => Results.Ok(new { status = "alive" }));
app.MapGet(
    "/health/ready",
    async (GuideDb db) =>
        await db.Database.CanConnectAsync()
            ? Results.Ok(new { status = "ready" })
            : Results.StatusCode(503)
);
app.MapFallback(async c =>
{
    if (c.Request.Path.StartsWithSegments("/api") || c.Request.Path.StartsWithSegments("/media"))
    {
        c.Response.StatusCode = 404;
        return;
    }
    var index = Path.Combine(
        app.Environment.WebRootPath ?? Path.Combine(app.Environment.ContentRootPath, "wwwroot"),
        "index.html"
    );
    if (File.Exists(index))
    {
        c.Response.ContentType = "text/html; charset=utf-8";
        c.Response.Headers.CacheControl = "no-cache";
        await c.Response.SendFileAsync(index);
    }
    else
    {
        c.Response.StatusCode = 404;
        await c.Response.WriteAsJsonAsync(
            new { detail = "Build the frontend before starting production." }
        );
    }
});
app.Run();

public partial class Program { }
